          const uploaded = Number(result?.uploaded || 0);
          const duplicates = Number(result?.duplicatesSkipped || 0);
          const blanks = Number(result?.blankRowsSkipped || 0);
          const errors = result?.errors || [];
          const notes = [duplicates ? `${duplicates} duplicate(s) skipped` : '', blanks ? `${blanks} blank row(s) skipped` : '', errors.length ? `${errors.length} row error(s)` : ''].filter(Boolean);
